WITH
CTE_COUNTRY as (select ID,case when id = 5 then 'D0' when id = 8 then 'F0' when id = 18 then 'NI' else COUNTRY end as COUNTRY from idq_results.REF_COUNTRY WHERE ID = (CASE WHEN ${COUNTRY_ID} = 17 /*MT*/ THEN 13 /*IT*/ WHEN ${COUNTRY_ID} = 18 /*NIE*/ THEN 12 /*IE*/ WHEN ${COUNTRY_ID} = 33 /*EE*/ THEN 34 /*LV*/ELSE ${COUNTRY_ID} END)),
CTE1 AS (SELECT DISTINCT MATNR, MATKL, SPLIT_PART(ZEINR,' ', -1) AS ZEINR FROM ZSM.MARA),
CTE2 AS (SELECT DISTINCT MATNR, MAKTX, CASE WHEN SPRAS = '늆' THEN 'BE' WHEN SPRAS = '늇' THEN 'AT' WHEN SPRAS = '뎧' THEN 'CH' WHEN SPRAS = '딥' THEN 'IE' WHEN SPRAS = 'W' THEN 'BG' WHEN SPRAS = 'C' THEN 'CZ' WHEN SPRAS = 'K' THEN 'DK' WHEN SPRAS = 'D' THEN 'D0' WHEN SPRAS = 'G' THEN 'GR' WHEN SPRAS = 'E' THEN 'GB' WHEN SPRAS = 'S' THEN 'ES' WHEN SPRAS = '9' THEN 'EE' WHEN SPRAS = 'U' THEN 'FI' WHEN SPRAS = 'F' THEN 'F0' WHEN SPRAS = '6' THEN 'HR' WHEN SPRAS = 'H' THEN 'HU' WHEN SPRAS = 'I' THEN 'IT' WHEN SPRAS = 'X' THEN 'LT' WHEN SPRAS = 'Y' THEN 'LV' WHEN SPRAS = '봔' THEN 'MT' WHEN SPRAS = 'N' THEN 'NL' WHEN SPRAS = 'L' THEN 'PL' WHEN SPRAS = 'P' THEN 'PT' WHEN SPRAS = '4' THEN 'RO' WHEN SPRAS = 'd' THEN 'RS' WHEN SPRAS = 'Q' THEN 'SK' WHEN SPRAS = '5' THEN 'SI' WHEN SPRAS = 'V' THEN 'SE' WHEN SPRAS = '(' THEN 'CS' WHEN SPRAS = ')' THEN 'CY' WHEN SPRAS = ',' THEN 'NI' END AS EKORG FROM ZSM.MAKT C1 INNER JOIN CTE_COUNTRY C2 ON LEFT(EKORG,2) = C2.COUNTRY),
CTE3 AS (SELECT DISTINCT MATNR, CASE WHEN (${COUNTRY_ID} IN (17,18,33) AND (NOT DESC_LONG_MLM IS NULL OR DESC_LONG_MLM <> ' ')) THEN DESC_LONG_MLM ELSE LONGDESC END AS LONGDESC, CASE WHEN (${COUNTRY_ID} IN (17,18,33) AND (NOT DESC_SHORT_MLM IS NULL OR DESC_SHORT_MLM <> ' ')) THEN DESC_SHORT_MLM ELSE NULL END AS SHORTDESC, DESC1,  DESC2, CASE WHEN ((TEMP_MIN = -273 AND TEMP_MAX = 9999 AND TEMP_MESS = 0) OR TEMP_MESS = 0) THEN NULL ELSE TEMP_MESS END as TEMP_MESS, CASE WHEN TEMP_MIN = -273 THEN NULL ELSE TO_NUMBER(TEMP_MIN, 10, 2) END AS TEMP_MIN, CASE WHEN TEMP_MAX = 9999 THEN NULL ELSE TO_NUMBER(TEMP_MAX, 10, 2) END AS TEMP_MAX,  CASE WHEN PLU = 0 THEN NULL ELSE PLU END AS PLU, EKORG, CASE WHEN ART_CAT = '1' THEN 'Neulistung EM' WHEN ART_CAT = '2' THEN 'Neulistung M' WHEN ART_CAT = '3' THEN 'Normalsortiment EM' WHEN ART_CAT = '4' THEN 'Normalsortiment M' WHEN ART_CAT = '5' THEN 'Aktionsartikel EM' WHEN ART_CAT = '6' THEN 'Aktionsartikel M' WHEN ART_CAT = '7' THEN 'Testartikel EM' WHEN ART_CAT = '8' THEN 'Testartikel M' WHEN ART_CAT = '9' THEN 'Auslistung EM' WHEN ART_CAT = '10' THEN 'Auslistung M' END AS ART_CAT, WSTAW FROM ZSM.ZSM_MM_OBSTGEM C1 INNER JOIN CTE_COUNTRY C2 ON LEFT(C1.EKORG,2) = C2.COUNTRY),
CTE4 AS (SELECT DISTINCT A.MATNR, B.ITEM_FAMILY_ID, B.NODE FROM (SELECT MATNR, NODE FROM ZSM.WRF_MATGRP_SKU) A INNER JOIN (SELECT NODE, LTRIM(SUBSTR(REGEXP_SUBSTR(LTEXT, '\\.(\\d+)'),2,3),0) AS ITEM_FAMILY_ID FROM ZSM.WRF_MATGRP_STRCT) B ON A.NODE = B.NODE),
CTE5 AS (SELECT C.MATNR, LISTAGG(C.MERKMALE, '|') WITHIN GROUP (ORDER BY C.MERKMALE) AS MERKMALE FROM (SELECT DISTINCT MATNR,CASE WHEN (ATINN = 5 AND ATWRT = 'JA') THEN 'INT_BIO' WHEN (ATINN = 28 AND ATWRT = 'INT_FAIRTRADE') THEN 'INT_Fairtrade' ELSE NULL END AS MERKMALE FROM (SELECT OBJEK AS MATNR, CUOBJ AS OBJEK FROM ZSM.INOB) AS A INNER JOIN (SELECT LTRIM(OBJEK, 0) AS OBJEK, ATINN, ATWRT FROM ZSM.AUSP WHERE (ATINN = 5 AND ATWRT = 'JA') OR (ATINN = 28 AND ATWRT = 'INT_FAIRTRADE')) B ON A.OBJEK = B.OBJEK) C GROUP BY C.MATNR),
CTE6 AS (SELECT DISTINCT MATNR, EAN11, EKORG FROM ZSM.ZSM_MM_MEAN_VEN C1 INNER JOIN CTE_COUNTRY C2 ON LEFT(C1.EKORG,2) = C2.COUNTRY)

SELECT DISTINCT
LTRIM(A.MATNR, 0)                                                       AS ARTIKELNR, 
CASE WHEN NOT C.SHORTDESC IS NULL THEN C.SHORTDESC ELSE B.MAKTX END     AS BEZ_KURZ, 
C.LONGDESC                                                              AS BEZ_LANG, 
C.DESC1                                                                 AS BEZ_KURZ2, 
C.DESC2                                                                 AS BEZ_KURZ3, 
A.ZEINR                                                                 AS PACK_TYPE, 
A.MATKL                                                                 AS ARTGRUPNR, 
D.ITEM_FAMILY_ID                                                        AS ITEMFAMILY_ID, 
E.MERKMALE                                                              AS MERKMALE, 
C.ART_CAT                                                               AS ARTICLE_CAT, 
C.TEMP_MESS                                                             AS TEMP_TYPE, 
C.TEMP_MIN                                                              AS TEMP_MIN, 
C.TEMP_MAX                                                              AS TEMP_MAX, 
C.PLU                                                                   AS PLU, 
F.EAN11                                                                 AS EANCODE,
C.WSTAW                                                                 AS INTRASTAT

FROM CTE1 A
LEFT JOIN CTE2 B ON A.MATNR = B.MATNR
LEFT JOIN CTE3 C ON A.MATNR = C.MATNR
LEFT JOIN CTE4 D ON A.MATNR = D.MATNR
LEFT JOIN CTE5 E ON A.MATNR = E.MATNR
LEFT JOIN CTE6 F ON A.MATNR = F.MATNR

-- ARTGRUPNR FILTER
WHERE A.MATKL IN (10,11,12,13)
-- EKORG FILTER
AND (NOT F.MATNR IS NULL OR NOT C.MATNR IS NULL)   
ORDER BY ARTIKELNR;